USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_AssetSpec_Create @AssetId BIGINT,@SpecName NVARCHAR(150),@SpecType VARCHAR(20),@IsMandatory BIT,@DisplayOrder INT,@IsActive BIT=1,@Actor VARCHAR(50)
AS BEGIN SET NOCOUNT ON; BEGIN TRY INSERT dbo.ASSET_SPEC_DEFINITION(ASSET_ID,SPEC_NAME,SPEC_TYPE,IS_MANDATORY,DISPLAY_ORDER,IS_ACTIVE,CREATED_BY) VALUES(@AssetId,@SpecName,@SpecType,@IsMandatory,@DisplayOrder,@IsActive,@Actor); SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,CONVERT(BIGINT,SCOPE_IDENTITY()) ENTITY_ID,NULL REFERENCE_NO; END TRY BEGIN CATCH SELECT CASE WHEN ERROR_NUMBER() IN(2601,2627) THEN '005' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,NULL ENTITY_ID,NULL REFERENCE_NO; END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_AssetSpec_Update @SpecId BIGINT,@SpecName NVARCHAR(150),@SpecType VARCHAR(20),@IsMandatory BIT,@DisplayOrder INT,@IsActive BIT,@Actor VARCHAR(50)
AS BEGIN SET NOCOUNT ON; UPDATE dbo.ASSET_SPEC_DEFINITION SET SPEC_NAME=@SpecName,SPEC_TYPE=@SpecType,IS_MANDATORY=@IsMandatory,DISPLAY_ORDER=@DisplayOrder,IS_ACTIVE=@IsActive,MODIFIED_BY=@Actor,MODIFIED_DATE=SYSUTCDATETIME() WHERE ASSET_SPEC_ID=@SpecId; SELECT CASE WHEN @@ROWCOUNT=1 THEN '000' ELSE '002' END RESULT_CODE,CASE WHEN @@ROWCOUNT=1 THEN N'Success' ELSE N'Not found' END RESULT_MESSAGE,@SpecId ENTITY_ID,NULL REFERENCE_NO; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_AssetSpecOption_Create @SpecId BIGINT,@OptionValue NVARCHAR(300),@DisplayOrder INT,@IsActive BIT=1,@Actor VARCHAR(50)
AS BEGIN SET NOCOUNT ON; BEGIN TRY IF NOT EXISTS(SELECT 1 FROM dbo.ASSET_SPEC_DEFINITION WHERE ASSET_SPEC_ID=@SpecId AND SPEC_TYPE IN('DROPDOWN','MULTI_SELECT')) THROW 51000,'Options require a DROPDOWN or MULTI_SELECT specification.',1; INSERT dbo.ASSET_SPEC_OPTION(ASSET_SPEC_ID,OPTION_VALUE,DISPLAY_ORDER,IS_ACTIVE,CREATED_BY) VALUES(@SpecId,@OptionValue,@DisplayOrder,@IsActive,@Actor); SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,CONVERT(BIGINT,SCOPE_IDENTITY()) ENTITY_ID,NULL REFERENCE_NO; END TRY BEGIN CATCH SELECT CASE WHEN ERROR_NUMBER()=51000 THEN '001' WHEN ERROR_NUMBER() IN(2601,2627) THEN '005' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,NULL ENTITY_ID,NULL REFERENCE_NO; END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_AssetSpecOption_Update @SpecId BIGINT,@OptionId BIGINT,@OptionValue NVARCHAR(300),@DisplayOrder INT,@IsActive BIT,@Actor VARCHAR(50)
AS BEGIN SET NOCOUNT ON; UPDATE dbo.ASSET_SPEC_OPTION SET OPTION_VALUE=@OptionValue,DISPLAY_ORDER=@DisplayOrder,IS_ACTIVE=@IsActive,MODIFIED_BY=@Actor,MODIFIED_DATE=SYSUTCDATETIME() WHERE ASSET_SPEC_OPTION_ID=@OptionId AND ASSET_SPEC_ID=@SpecId; SELECT CASE WHEN @@ROWCOUNT=1 THEN '000' ELSE '002' END RESULT_CODE,CASE WHEN @@ROWCOUNT=1 THEN N'Success' ELSE N'Not found' END RESULT_MESSAGE,@OptionId ENTITY_ID,NULL REFERENCE_NO; END;
GO
